package Inheritance;class parent{   void show(){        System.out.println("parent class");    }}class child extends parent{    @Override    void show(){        System.out.println("child class");    }}public class METHODOVERRIDING {    public static void main(String[] args) {        int a,b;        parent c1=new child();        parent c2=new parent();        child c3=new child();        c1.show();        c2.show();        c3.show();    }}